//! Minimal re-implementation of the `sortedcontainers` C++ interface
//! used by the tests, backed by `std::collections::BTreeMap`.

pub mod sorted_map;

pub use sorted_map::SortedMap;

/// Free function mirroring `sortedcontainers::update(m, other)`:
/// inserts all key/value pairs of `other` into `m`, overwriting
/// existing keys.
pub fn update<K, V>(m: &mut SortedMap<K, V>, other: SortedMap<K, V>)
where
    K: Ord,
{
    for (k, v) in other.into_iter() {
        m.insert(k, v);
    }
}

//! A sorted associative container mirroring the subset of the C++
//! `SortedMap` API exercised by the tests. Keys are kept in ascending
//! order; implemented on top of `std::collections::BTreeMap`.

use std::collections::btree_map::{self, BTreeMap};
use std::ops::{Bound, RangeBounds};

pub struct SortedMap<K, V> {
    inner: BTreeMap<K, V>,
}

impl<K: Ord, V> SortedMap<K, V> {
    pub fn new() -> Self {
        SortedMap {
            inner: BTreeMap::new(),
        }
    }

    /// Number of elements in the map.
    pub fn size(&self) -> usize {
        self.inner.len()
    }

    /// Whether the map contains no elements.
    pub fn empty(&self) -> bool {
        self.inner.is_empty()
    }

    /// Insert a key/value pair, overwriting any existing value for `key`.
    pub fn insert(&mut self, key: K, value: V) {
        self.inner.insert(key, value);
    }

    /// Whether `key` is present in the map.
    pub fn contains(&self, key: &K) -> bool {
        self.inner.contains_key(key)
    }

    /// Mutable access mirroring C++ `operator[]`: inserts
    /// `V::default()` when the key is absent.
    pub fn at_or_default(&mut self, key: K) -> &mut V
    where
        V: Default,
    {
        self.inner.entry(key).or_default()
    }

    /// Look up `key`, returning `default` when absent.
    pub fn get<'a>(&'a self, key: &K, default: &'a V) -> &'a V {
        self.inner.get(key).unwrap_or(default)
    }

    /// Remove `key` if present.
    pub fn erase(&mut self, key: &K) {
        self.inner.remove(key);
    }

    /// Remove all elements.
    pub fn clear(&mut self) {
        self.inner.clear();
    }

    /// All keys in ascending order.
    pub fn keys(&self) -> Vec<&K> {
        self.inner.keys().collect()
    }

    /// All values in ascending key order.
    pub fn values(&self) -> Vec<&V> {
        self.inner.values().collect()
    }

    /// Iterator over the entry with the given key, if present.
    pub fn find(&self, key: &K) -> Option<(&K, &V)> {
        self.inner.get_key_value(key)
    }

    /// First entry not less than `key`.
    pub fn lower_bound(&self, key: &K) -> Option<(&K, &V)> {
        self.inner.range((Bound::Included(key), Bound::Unbounded)).next()
    }

    /// First entry greater than `key`.
    pub fn upper_bound(&self, key: &K) -> Option<(&K, &V)> {
        self.inner.range((Bound::Excluded(key), Bound::Unbounded)).next()
    }

    /// Range of entries whose key equals `key` (at most one element).
    pub fn equal_range<R>(&self, range: R) -> btree_map::Range<'_, K, V>
    where
        R: RangeBounds<K>,
    {
        self.inner.range(range)
    }
}

impl<K: Ord, V> IntoIterator for SortedMap<K, V> {
    type Item = (K, V);
    type IntoIter = btree_map::IntoIter<K, V>;

    fn into_iter(self) -> Self::IntoIter {
        self.inner.into_iter()
    }
}

impl<K: Ord, V> Default for SortedMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

use sortedcontainers::{update, SortedMap};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 18;
    if args.len() > 1 {
        n = args[1].parse().unwrap_or(0);
    }

    let mut m: SortedMap<(i32, i32), String> = SortedMap::new();
    for i in 0..n {
        let key = (i, i * 2);
        m.insert(key, format!("value_{}", i));
    }

    println!("{}", m.size());

    let test_key1 = (3, 6);
    let test_key2 = (5, 10);

    println!("{}", m.contains(&test_key1) as i32);
    println!("{}", m.contains(&test_key2) as i32);

    println!("{}", m.at_or_default(test_key1));

    *m.at_or_default(test_key1) = "modified".to_string();
    println!("{}", m.at_or_default(test_key1));

    let keys = m.keys();
    let values = m.values();

    println!("{}", keys.len());
    println!("{}", values.len());

    for i in 0..4 {
        let key_to_remove = (i, i * 2);
        m.erase(&key_to_remove);
    }

    println!("{}", m.size());

    if let Some((_, value)) = m.find(&(6, 12)) {
        println!("{}", value);
    }

    if let Some((key, _)) = m.lower_bound(&(7, 14)) {
        println!("{}", key.0);
    }

    if let Some((key, _)) = m.upper_bound(&(7, 14)) {
        println!("{}", key.0);
    }

    let mut m2: SortedMap<(i32, i32), String> = SortedMap::new();
    for i in 0..n / 2 {
        let key = (i + 10, (i + 10) * 2);
        m2.insert(key, format!("other_{}", i));
    }

    update(&mut m, m2);

    println!("{}", m.size());
    println!("{}", m.contains(&(12, 24)) as i32);

    let count = m.equal_range((8, 16)..=(8, 16)).count();
    println!("{}", count);

    println!("{}", m.get(&(100, 200), &"default".to_string()));

    m.clear();

    println!("{}", m.size());
    println!("{}", m.empty() as i32);
}

