/// Matches C++ `std::atoi`: skips leading whitespace, parses an
/// optional sign followed by a run of digits, returns 0 on failure.
fn atoi(s: &str) -> i32 {
    let s = s.trim_start();
    let (sign, digits) = match s.as_bytes().first() {
        Some(b'-') => (-1i64, &s[1..]),
        Some(b'+') => (1i64, &s[1..]),
        _ => (1i64, s),
    };
    let mut value: i64 = 0;
    for &b in digits.as_bytes() {
        if !b.is_ascii_digit() {
            break;
        }
        value = value * 10 + (b - b'0') as i64;
    }
    (sign * value) as i32
}

